/**
 * validator.ts — 群像蒸馏校验审核器
 *
 * 用途：验证群像蒸馏产出的质量，检测角色可信度、协议配置可追溯性、
 *       7条红线违规、以及模板的整体合规性。
 *
 * 参考类型：
 *   - src/types.ts:          GapDimension, TeamProtocol, etc.
 *   - Schema v4.0 接口契约：   TeamTemplateSkeleton, ProbeReport, etc.
 *
 * 审核标准：docs/group-distill/VALIDATION-STANDARDS.md
 *
 * @package Synova
 */
/** 群像蒸馏产出的团队模板骨架 */
export interface TeamTemplateSkeleton {
    /** 模板唯一标识 */
    templateId: string;
    /** 角色列表（群像蒸馏产出的心智模型集合） */
    roles: RoleDefinition[];
    /** 协议配置（6缝隙或6缝隙） */
    protocol?: ProtocolConfig;
    /** 角色间两两对比冲突矩阵（用于自洽性检查） */
    conflictMatrix?: ConflictEntry[];
    /** 诚实边界声明 */
    honestBoundaries: string[];
    /** 反模式列表 */
    antiPatterns: AntiPattern[];
    /** 推导方法说明 */
    derivationNotes: string[];
}
/** 探针报告——蒸馏的信源证据集合 */
export interface ProbeReport {
    /** 本次蒸馏的探针标识 */
    probeId: string;
    /** 扫描的行业/领域 */
    domain: string;
    /** 扫描的平台列表 */
    platforms: string[];
    /** 采集的信源条目 */
    sources: Source[];
    /** 扫描时间 */
    scanTime: string;
    /** 采集的数据类型 */
    dataTypes: ProbeDataType[];
}
type ProbeDataType = 'job_description' | 'industry_report' | 'community_post' | 'interview_record' | 'textbook_excerpt' | 'platform_rule' | 'case_study' | 'other';
/** 单条信源 */
export interface Source {
    /** 信源唯一标识 */
    id: string;
    /** 信源类型 */
    type: ProbeDataType;
    /** 信源名称/标题 */
    title: string;
    /** 信源URL或出处 */
    url?: string;
    /** 平台/来源平台 */
    platform?: string;
    /** 信源可信度分级（VALIDATION-STANDARDS.md 中的 L1-L5） */
    tier: 1 | 2 | 3 | 4 | 5;
    /** 信源摘要 */
    summary: string;
    /** 该信源支撑的心智模型ID列表 */
    supportsModelIds: string[];
    /** 该信源支撑的协议缝隙 */
    supportsGaps?: string[];
}
/** 角色定义 */
export interface RoleDefinition {
    /** 角色唯一标识 */
    id: string;
    /** 角色名称 */
    name: string;
    /** 推导可信度（VALIDATION-STANDARDS.md 中的 L1-L5） */
    credibilityLevel: 1 | 2 | 3 | 4 | 5;
    /** 心智模型列表 */
    mentalModels: MentalModel[];
    /** 推导说明 */
    derivationNotes: string[];
    /** 诚实边界（针对该角色） */
    honestBoundaries: string[];
}
/** 心智模型 */
export interface MentalModel {
    /** 模型ID */
    id: string;
    /** 模型名称 */
    name: string;
    /** 一句话描述 */
    oneLiner: string;
    /** 来源框架 */
    source: string;
    /** 应用场景 */
    application: string;
    /** 局限性 */
    limitation: string;
    /** 适用决策场景 */
    decisionScenarios: string[];
    /** 反模式列表 */
    antiPatternIds: string[];
    /** 支撑信源ID列表 */
    sourceIds: string[];
}
/** 协议配置 */
export interface ProtocolConfig {
    /** 协同模式 */
    mode: CollaborationMode;
    /** 6缝隙配置 */
    gaps: {
        divisionOfLabor: GapConfig;
        informationFlow: GapConfig;
        authorityGovernance: GapConfig;
        trustIncentive: GapConfig;
    };
    /** 每条规则的来源 */
    ruleSources: RuleSource[];
}
interface GapConfig {
    value: string;
    confidence: 'high' | 'medium' | 'low' | 'default';
    sourceIds: string[];
    note?: string;
}
type CollaborationMode = 'iron_captain' | 'democratic_assembly' | 'loose_federation' | 'cross_checks';
interface RuleSource {
    ruleId: string;
    sourceType: 'constraint' | 'celebrity_mode' | 'group_image' | 'user_override';
    sourceDetail: string;
}
/** 冲突记录（两两对比用） */
export interface ConflictEntry {
    modelAId: string;
    modelBId: string;
    conflictType: 'fatal' | 'severe' | 'mild' | 'complementary';
    description: string;
    severity: number;
    resolution?: string;
}
/** 反模式 */
export interface AntiPattern {
    id: string;
    pattern: string;
    description: string;
    boundModelIds: string[];
}
/** 审核报告 */
export interface ValidationReport {
    /** 模板ID */
    templateId: string;
    /** 总体结果 */
    overall: 'passed' | 'conditional_pass' | 'failed';
    /** 各维度评分 */
    scores: {
        rationality: number;
        selfConsistency: SelfConsistencyResult;
        operability: number;
        sourceStrength: number;
    };
    /** 7条红线检查结果 */
    redlineResults: RedlineResult[];
    /** 协议可追溯性报告（如有协议配置） */
    traceability?: TraceabilityReport;
    /** 角色可信度明细 */
    roleCredibilityScores: CredibilityScore[];
    /** 红线违规列表 */
    redlineViolations: string[];
    /** 警告列表 */
    warnings: string[];
    /** 建议 */
    recommendations: string[];
    /** 审核时间 */
    validatedAt: string;
}
/** 自洽性检查结果 */
export interface SelfConsistencyResult {
    status: 'passed' | 'conditional' | 'failed';
    fatalConflicts: number;
    severeConflicts: number;
    mildConflicts: number;
    complementaryPairs: number;
    conflictDetails: ConflictEntry[];
    recommendation?: string;
}
/** 红线检查结果 */
export interface RedlineResult {
    ruleId: number;
    name: string;
    passed: boolean;
    severity: 'error' | 'warning' | 'info';
    detail: string;
}
/** 角色可信度评分 */
export interface CredibilityScore {
    roleId: string;
    roleName: string;
    /** L1-L5 可信度等级 */
    credibilityLevel: 1 | 2 | 3 | 4 | 5;
    /** 支撑信源数量 */
    sourceCount: number;
    /** 是否有诚实边界 */
    hasHonestBoundaries: boolean;
    /** 心智模型完整性（所有必要字段是否齐全） */
    modelCompleteness: boolean;
    /** 反模式绑定率 */
    antiPatternBindingRate: number;
    /** 总体评分 0-100 */
    totalScore: number;
    warnings: string[];
}
/** 协议可追溯性报告 */
export interface TraceabilityReport {
    /** 探针标识 */
    probeId: string;
    /** 每个缝隙的可追溯状态 */
    gapTraceability: GapTraceabilityEntry[];
    /** 无信源支撑的规则数 */
    unsourcedRules: number;
    /** 总规则数 */
    totalRules: number;
    /** 整体可追溯率 */
    traceabilityRate: number;
    /** 警告 */
    warnings: string[];
}
interface GapTraceabilityEntry {
    gapName: string;
    confidence: 'high' | 'medium' | 'low' | 'default';
    sourceCount: number;
    sources: string[];
    traceable: boolean;
}
/**
 * 审核群像蒸馏产出的整体质量
 *
 * @param template - 群像蒸馏产出的团队模板
 * @param probeReport - 探针报告（信源证据集合）
 * @returns ValidationReport - 完整的审核报告
 */
export declare function validateGroupDistill(template: TeamTemplateSkeleton, probeReport: ProbeReport): ValidationReport;
/**
 * 检查单条角色的可信度
 *
 * @param role - 角色定义
 * @param sources - 探针信源集合
 * @returns CredibilityScore - 角色可信度评分
 */
export declare function checkRoleCredibility(role: RoleDefinition, sources: Source[]): CredibilityScore;
/**
 * 检查协议配置是否来自探针证据的可追溯性
 *
 * @param protocol - 协议配置
 * @param probeReport - 探针报告
 * @returns TraceabilityReport - 可追溯性报告
 */
export declare function checkProtocolTraceability(protocol: ProtocolConfig, probeReport: ProbeReport): TraceabilityReport;
export {};
